function refreshBatch(batchId) {
  const batch = store.importBatches.find(x => x.id === batchId); if (!batch) return;
  const items = store.importItems.filter(x => x.batchId === batchId);
  batch.validRows = items.filter(x => !['error','excluded'].includes(x.status)).length;
  batch.reviewRows = items.filter(x => x.status === 'needs_human_review').length;
  batch.excludedRows = items.filter(x => x.status === 'excluded').length;
  batch.errorRows = items.filter(x => x.status === 'error').length;
  batch.status = batch.errorRows ? 'needs_correction' : 'ready';
}
