function memberVerificationRows(){const rows=Object.values(store.users).map(user=>{const decision=evaluateMembership(user),payments=store.paymentEvidence.filter(x=>x.userId===user.id),ocr=store.groupLabelOcrResults.find(x=>x.candidateUserId===user.id),paymentSources={wechatShop:payments.some(x=>['wechat_shop_order','shop_evidence'].includes(x.source)),wechatMerchant:payments.some(x=>x.source==='wechat_merchant_receipt'),manualTransfer:payments.some(x=>['manual_transfer','manual_payment'].includes(x.source))},missingItems=[];if(user.crmVerificationStatus!=='verified')missingItems.push('CRM 待补全');if(!payments.some(x=>x.evidenceStatus==='verified'))missingItems.push('付款线索待复核');if(!ocr)missingItems.push('群标签待导入或手工确认');if(user.groupStatus==='unknown')missingItems.push('大群状态待确认');return {id:user.id,alias:user.nickname,matchStatus:user.matchStatus||'matched',groupStatus:user.groupStatus,groupLabel:user.groupLabel||'待人工补录',groupLabelExpiry:user.groupLabelExpiry||user.endsAt,ocrStatus:ocr?.reviewStatus||'not_imported',ocrConfidenceBand:ocr?.confidenceBand||null,paymentSources,missingItems,crmCompletionStatus:user.crmVerificationStatus==='verified'?'complete':'needs_completion',renewalNoticeStatus:user.renewalNoticeStatus||'not_recorded',operatorDecision:decision.operationalStatus,currentMembershipStatus:decision.active?'active':'needs_review',temporarilyActive:Boolean(decision.renewalHold),publicDirectoryChanged:false}});const unmatched=store.groupLabelOcrResults.filter(x=>!x.candidateUserId).map(x=>({id:x.id,alias:x.alias,matchStatus:'unmatched',groupStatus:'unknown',groupLabel:x.labelSuggestion,groupLabelExpiry:x.expirySuggestion,ocrStatus:x.reviewStatus,ocrConfidenceBand:x.confidenceBand,paymentSources:{wechatShop:false,wechatMerchant:false,manualTransfer:false},missingItems:['匹配成员','CRM 手工补录','大群状态确认'],crmCompletionStatus:'needs_completion',renewalNoticeStatus:'not_recorded',operatorDecision:'manual_match_required',currentMembershipStatus:'needs_review',temporarilyActive:false,publicDirectoryChanged:false}));return [...rows,...unmatched]}
